/**
 * Cancel a running job.
 */
export async function cancelJob(jobId: string): Promise<{
  cancelled: boolean;
  error?: string;
}> {
  const job = _activeJobs.get(jobId);
  if (!job) {
    return { cancelled: false, error: `Job ${jobId} not found` };
  }

  if (job.status !== 'running') {
    return { cancelled: false, error: `Job ${jobId} is already ${job.status}` };
  }

  // Try to cancel via MCP
  try {
    await execFileAsync(
      getMcpCliBinary(),
      ['tool', 'call', 'gravito.cancelJob', '--server', _syncConfig.mcpServerName,
        '--input', JSON.stringify({ job_id: jobId })],
      { timeout: 10_000 }
    );
  } catch {
    // Best effort — mark as cancelled locally regardless
  }

  job.status = 'cancelled';
  job.completedAt = Date.now();

  return { cancelled: true };
}

// ============================================================================
// METRICS
// ============================================================================

export function getSyncWrapperMetrics(): SyncWrapperMetrics {
  return { ..._syncMetrics };
}

// ============================================================================
// HELPERS
// ============================================================================

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function updateAvgWaitTime(waitTimeMs: number): void {
  const total = _syncMetrics.jobsCompletedSync;
  if (total <= 1) {
    _syncMetrics.avgWaitTimeMs = waitTimeMs;
  } else {
    _syncMetrics.avgWaitTimeMs = Math.round(
      (_syncMetrics.avgWaitTimeMs * (total - 1) + waitTimeMs) / total
    );
  }
}

