tool_use_result.originalFile:
/**
 * Governance Dashboard Router — /admin/governance
 * 
 * Backend procedures for the 3-panel governance dashboard:
 * 
 * Panel 1: Transport Health
 *   - Current transport mode (HTTP / CLI / disabled)
 *   - Transport metrics (success rate, latency p50/p95/p99, failures)
 *   - Prometheus-format export
 * 
 * Panel 2: Authority Decisions
 *   - Recent decisions with external/internal/merge breakdown
 *   - Decision statistics (total, success rate, avg latency)
 *   - Merge strategy distribution
 *   - Audit trail entries
 * 
 * Panel 3: Regulated Flow
 *   - Pre-approval metrics (requested, granted, denied, fail-closed)
 *   - Regulated vs non-regulated breakdown
 *   - Active approval tokens
 *   - Header injection stats
 */

import { z } from 'zod';
import { router, adminProcedure, protectedProcedure } from '../_core/trpc';
import { getExternalTransportStatus, getTransportMetrics, exportPrometheusMetrics } from './production-transport-selector';
import { getAuthorityMetrics, getAuthorityLayerHealth, getAuthorityAuditTrail } from './gravito-authority-layer';
import { getExternalGravitoHealth } from './gravito-external-client';
import { getPreApprovalMetrics, REGULATED_SURFACES } from './regulated-surface-preapproval';
import { getSyncWrapperMetrics, listJobs } from './mcp-sync-wrapper';
import { getAuthorityAuditEntries, getAuthorityAuditStats } from '../db';
import { getGovernanceUptimeMetrics, getInlineMetrics, getCircuitBreakerState, getAuthorityAuditSummary } from './co-processor/gravito-inline-client';
import type { AuthorityAuditEntry } from '../../shared/governance-types';

// ============================================================================
// PANEL 1: TRANSPORT HEALTH
// ============================================================================

/** Upper bound on jobs the sync wrapper keeps in its active-job table. */
const MAX_TRACKED_JOBS = 100;

const transportHealthProcedure = adminProcedure.query(async () => {
  const status = getExternalTransportStatus();
  const metrics = getTransportMetrics();
  const externalHealth = getExternalGravitoHealth();
  const syncMetrics = getSyncWrapperMetrics();

  // The transport tracks successes and failures separately; total is their sum.
  const totalTransportCalls = metrics.successesTotal + metrics.failuresTotal;

  return {
    // Current state
    transport: {
      enabled: status.enabled,
      mode: status.mode,
      reason: status.reason,
      environment: status.environment,
      lastError: status.lastError,
      lastSuccessAt: status.lastSuccessAt,
    },

    // Performance metrics
    performance: {
      totalCalls: totalTransportCalls,
      successCount: metrics.successesTotal,
      failureCount: metrics.failuresTotal,
      successRate: totalTransportCalls > 0
        ? Math.round((metrics.successesTotal / totalTransportCalls) * 10000) / 100
        : 0,
      latency: {
        p50: metrics.latencyP50Ms,
        p95: metrics.latencyP95Ms,
        p99: metrics.latencyP99Ms,
      },
      transportSwitches: metrics.transportSwitchCount,
    },

    // External client health
    externalClient: {
      circuitBreakerState: externalHealth.circuitBreakerState,
      totalCalls: externalHealth.totalCalls,
      successRate: externalHealth.totalCalls > 0
        ? Math.round((externalHealth.successfulCalls / externalHealth.totalCalls) * 10000) / 100
        : 0,
      averageLatencyMs: externalHealth.averageLatencyMs,
      fallbackRate: externalHealth.fallbackRate,
      lastError: externalHealth.lastFailureReason,
    },

    // Sync wrapper stats
    syncWrapper: {
      totalSubmissions: syncMetrics.asyncJobsDetected,
      syncResolved: syncMetrics.jobsCompletedSync,
      asyncReturned: syncMetrics.jobsTimedOut,
      pollAttempts: syncMetrics.totalPollAttempts,
      pollSuccesses: syncMetrics.jobsCompletedSync,
      pollTimeouts: syncMetrics.jobsTimedOut,
      activeJobs: listJobs({ statusFilter: 'running', limit: MAX_TRACKED_JOBS }).length,
    },
  };
});

// ============================================================================
// PANEL 2: AUTHORITY DECISIONS
// ============================================================================

const authorityDecisionsProcedure = adminProcedure
  .input(z.object({
    days: z.number().min(1).max(90).default(7),
    limit: z.number().min(1).max(500).default(50),
    surfaceType: z.string().optional(),
    regulated: z.boolean().optional(),
  }).optional())
  .query(async ({ input }) => {
    const opts = input || { days: 7, limit: 50 };

    // Get authority layer metrics
    const authorityMetrics = getAuthorityMetrics();
    const authorityHealth = getAuthorityLayerHealth();

    // Get inline client metrics
    const inlineMetrics = getInlineMetrics();
    const breakerState = getCircuitBreakerState();
    const uptimeMetrics = getGovernanceUptimeMetrics();

    // Get in-memory audit trail (fast)
    const memoryAuditTrail = getAuthorityAuditSummary();

    // Get database-backed stats (durable)
    const dbStats = await getAuthorityAuditStats(opts.days);

    // Get recent audit entries from database
    const sinceTimestamp = Date.now() - (opts.days * 24 * 60 * 60 * 1000);
    const recentEntries = await getAuthorityAuditEntries({
      limit: opts.limit,
      surfaceType: opts.surfaceType,
      regulated: opts.regulated,
      sinceTimestamp,
    });

    return {
      // Summary statistics
      summary: {
        totalDecisions: dbStats.totalDecisions,
        externalSuccessRate: Math.round(dbStats.externalSuccessRate * 10000) / 100,
        avgLatencyMs: dbStats.avgLatencyMs,
        regulatedDecisions: dbStats.regulatedDecisions,
        blockedDecisions: dbStats.blockedDecisions,
        mergeStrategyCounts: dbStats.mergeStrategyCounts,
        periodDays: opts.days,
      },

      // Authority layer state
      authorityLayer: {
        status: authorityHealth.status,
        statusReason: authorityHealth.statusReason,
        externalReachable: authorityHealth.external.reachable,
        metrics: {
          externalSuccesses: authorityMetrics.externalSuccesses,
          externalFailures: authorityMetrics.externalFailures,
          internalFallbacks: authorityMetrics.internalFallbacks,
          failClosedEvents: authorityMetrics.failClosedEvents,
          mergedDecisions: authorityMetrics.mergedDecisions,
        },
      },

      // Inline client state
      inlineClient: {
        circuitBreakerState: breakerState,
        totalCalls: inlineMetrics.totalCalls,
        successRate: inlineMetrics.successRate,
        avgLatencyMs: inlineMetrics.avgLatencyMs,
        uptime: uptimeMetrics,
      },

      // In-memory audit summary
      memoryAudit: memoryAuditTrail,

      // Recent database entries
      recentEntries: recentEntries.map((entry: AuthorityAuditEntry) => ({
        id: entry.id,
        surfaceType: entry.surfaceType,
        regulated: entry.regulated,
        externalAttempted: entry.externalAttempted,
        externalSuccess: entry.externalSuccess,
        mergeStrategy: entry.mergeStrategy,
        finalApproved: entry.finalApproved,
        finalSeverity: entry.finalSeverity,
        totalLatencyMs: entry.totalLatencyMs,
        createdAt: entry.createdAt,
      })),
    };
  });

// ============================================================================
// PANEL 3: REGULATED FLOW
// ============================================================================

const regulatedFlowProcedure = adminProcedure.query(async () => {
  const preApprovalMetrics = getPreApprovalMetrics();
  const authorityMetrics = getAuthorityMetrics();

  // Get regulated-only audit entries from DB
  const regulatedEntries = await getAuthorityAuditEntries({
    regulated: true,
    limit: 50,
    sinceTimestamp: Date.now() - (7 * 24 * 60 * 60 * 1000),
  });

  return {
    // Pre-approval metrics
    preApproval: {
      requested: preApprovalMetrics.preApprovalsRequested,
      granted: preApprovalMetrics.preApprovalsGranted,
      denied: preApprovalMetrics.preApprovalsDenied,
      failClosed: preApprovalMetrics.failClosedEvents,
      approvalRate: preApprovalMetrics.preApprovalsRequested > 0
        ? Math.round((preApprovalMetrics.preApprovalsGranted / preApprovalMetrics.preApprovalsRequested) * 10000) / 100
        : 0,
    },

    // Regulated review metrics
    regulatedReviews: {
      attempted: preApprovalMetrics.regulatedReviewsAttempted,
      blocked: preApprovalMetrics.regulatedReviewsBlocked,
      blockRate: preApprovalMetrics.regulatedReviewsAttempted > 0
        ? Math.round((preApprovalMetrics.regulatedReviewsBlocked / preApprovalMetrics.regulatedReviewsAttempted) * 10000) / 100
        : 0,
    },

    // Header injection stats
    headerInjection: {
      totalInjected: preApprovalMetrics.headersInjected,
      schemaNormalizations: preApprovalMetrics.schemaNormalizations,
    },

    // Authority layer fail-closed events
    failClosed: {
      total: authorityMetrics.failClosedEvents,
      description: 'Regulated content blocked because external Gravito was unavailable',
    },

    // Regulated surface types
    regulatedSurfaces: Array.from(REGULATED_SURFACES),

    // Recent regulated decisions
    recentRegulatedDecisions: regulatedEntries.map((entry: AuthorityAuditEntry) => ({
      id: entry.id,
      surfaceType: entry.surfaceType,
      externalAttempted: entry.externalAttempted,
      externalSuccess: entry.externalSuccess,
      mergeStrategy: entry.mergeStrategy,
      finalApproved: entry.finalApproved,
      finalSeverity: entry.finalSeverity,
      totalLatencyMs: entry.totalLatencyMs,
      createdAt: entry.createdAt,
    })),
  };
});

// ============================================================================
// PROMETHEUS EXPORT
// ============================================================================

const prometheusExportProcedure = adminProcedure.query(() => {
  return {
    metrics: exportPrometheusMetrics(),
    timestamp: Date.now(),
  };
});

// ============================================================================
// COMBINED OVERVIEW (all 3 panels in one call)
// ============================================================================

const overviewProcedure = adminProcedure
  .input(z.object({
    days: z.number().min(1).max(90).default(7),
  }).optional())
  .query(async ({ input }) => {
    const days = input?.days || 7;

    // Gather all data in parallel
    const [
      transportStatus,
      transportMetrics,
      externalHealth,
      syncMetrics,
      authorityMetrics,
      authorityHealth,
      preApprovalMetrics,
      dbStats,
      recentEntries,
    ] = await Promise.all([
